func printBadgeTable(badgesResult []badges.Badge) {
	for _, badge := range badgesResult {
		badgeGrantedStr, badgeGrantedColor := badgeGrantedToStrAndColor(badge.BadgeGranted)

		t := table.NewWriter()
		t.SetOutputMirror(os.Stdout)
		t.SetTitle(fmt.Sprintf("BadgeReport for %s (%s) - %s", badge.BadgeName, badge.BadgeLevel, badgeGrantedColor.Sprint(badgeGrantedStr)))
		t.AppendHeader(table.Row{"Check", "Status", "Description", "Evidence"})

		for _, criteria := range badge.BadgeExplanation.Criteria {
			fgColor := statusToColor(criteria.Status)
			t.AppendRow(table.Row{
				strings.Split(criteria.RuleID, ":")[0],
				fgColor.Sprint(criteria.Status),
				text.WrapSoft(criteria.Description, tableColumnWidth),
				text.WrapSoft(criteria.Evidence, tableColumnWidth),
			})
		}

		t.SetColumnConfigs([]table.ColumnConfig{
			{Number: 1, WidthMin: 16, WidthMax: 16},
			{Number: 2, Align: text.AlignCenter, AlignHeader: text.AlignCenter, WidthMin: 14, WidthMax: 14},
			{Number: 3, WidthMin: tableColumnWidth, WidthMax: tableColumnWidth},
			{Number: 4, WidthMin: tableColumnWidth, WidthMax: tableColumnWidth},
		})
		t.SetStyle(table.StyleLight)
		// t.SetStyle(table.StyleColoredBright)
		t.Style().Options.SeparateRows = true

		t.Render()
	}
}

func badgeGrantedToStrAndColor(granted bool) (string, text.Color) {
	badgeGrantedStr := "Not Granted"
	badgeGrantedColor := text.FgRed
	if granted {
		badgeGrantedStr = "Granted"
		badgeGrantedColor = text.FgGreen
	}
	return badgeGrantedStr, badgeGrantedColor
}

func statusToColor(status badges.Status) text.Color {
	// same color logik as in: https://gitlab.opencode.de/open-code/badgebackend/gitlab-profile/-/blob/main/src/components/ResultTable.tsx#L174
	switch status {
	case badges.StatusPass:
		return text.FgGreen
	case badges.StatusMissingData, badges.StatusTechnicalFailure:
		return text.FgWhite
	default:
		return text.FgRed
	}
}

